+const ROOT = path.resolve(
+  path.dirname(fileURLToPath(import.meta.url)),
+  "../..",
+);
+
+async function readText(relativePath: string): Promise<string> {
+  return fs.readFile(path.join(ROOT, relativePath), "utf8");
+}
